// Verbatim assembled original CotW UI strings, source manifest in work/batch01454.
using System;
using System.Collections.Generic;
namespace CallOfTheWild.Wrath.Prototype {
 internal static class MindbladeTexts01454 {
  static readonly Dictionary<string,string[]> Rows=new Dictionary<string,string[]> {
   {"MindBladePsychicSpellCasting",new[]{"Psychic Spell Casting","A mindblade casts psychic spells from magus spell list as psychic spells. To learn or cast a spell, a mindblade must have an Intelligence score equal to at least 10 + the spell’s level. The saving throw DC against a mindblade’s spell is 10 + the spell’s level + the mindblade’s Intelligence modifier.\nA mindblade need not prepare her spells in advance.\nShe can cast any magus spell she knows at any time, assuming she has not yet used up her allotment of spells per day for the spell’s level.\nMindblade spells are not subject to arcane spell failure due to armor, but they require a more significant effort, compared to classic magic and thus the DC of all concentration checks required as a part of casting a psychic spell is increased by 10, additionaly psychic magic can not be used at all if caster is under the influence of fear or negative emotion effects."}},
   {"PsychicAccessFeatureSelection",new[]{"Psychic Access","At 4th level, the mindblade can add a psychic spell to the list of her spells known. These must be a spell of level the mindblade is able to cast. At 7th, 11th, 14th, and 19th levels, she adds one more psychic class spell to her list of spells known, following the same restrictions.\nWhen a mindblade takes the spell blending arcana, she gains spells from the psychic class spell list instead of the wizard spell list."}},
   {"MindBladeWeaponEnchancementBrilliantEnergy",new[]{"Psychic Weapon - Brilliant Energy","A mindblade can add the brilliant energy property to her psychic weapon, but this consumes 4 points of enhancement bonus granted to this weapon.\nA brilliant energy weapon ignores nonliving matter.Armor and shield bonuses to AC (including any enhancement bonuses to that armor) do not count against it because the weapon passes through armor. (Dexterity, deflection, dodge, natural armor, and other such bonuses still apply.) A brilliant energy weapon cannot harm undead, constructs, or objects."}},
   {"MindBladeWeaponEnchancementFlaming",new[]{"Psychic Weapon - Flaming","A mindblade can add the flaming property to her psychic weapon, but this consumes 1 point of enhancement bonus granted to this weapon.\nA flaming weapon is sheathed in fire that deals an extra 1d6 points of fire damage on a successful hit. The fire does not harm the wielder."}},
   {"MindBladeWeaponEnchancementSpeed",new[]{"Psychic Weapon - Speed","A mindblade can add the speed property to her psychic weapon, but this consumes 3 points of enhancement bonus granted to this weapon.\nWhen making a full attack, the wielder of a speed weapon may make one extra attack with it. The attack uses the wielder's full base attack bonus, plus any modifiers appropriate to the situation. (This benefit is not cumulative with similar effects, such as a haste spell.)"}},
   {"MindBladeWeaponEnchancementFrost",new[]{"Psychic Weapon - Frost","A mindblade can add the frost property to her psychic weapon, but this consumes 1 point of enhancement bonus granted to this weapon.\nA frost weapon is sheathed in a terrible, icy cold that deals an extra 1d6 points of cold damage on a successful hit. The cold does not harm the wielder."}},
   {"MindBladeWeaponEnchancementShock",new[]{"Psychic Weapon - Shock","A mindblade can add the shock property to her psychic weapon, but this consumes 1 point of enhancement bonus granted to this weapon.\nA shock weapon is sheathed in crackling electricity that deals an extra 1d6 points of electricity damage on a successful hit. The electricity does not harm the wielder."}},
   {"MindBladeWeaponEnchancementGhostTouch",new[]{"Psychic Weapon - Ghost Touch","A mindblade can add the ghost touch property to her psychic weapon, but this consumes 1 point of enhancement bonus granted to this weapon.\nA ghost touch weapon deals damage normally against incorporeal creatures, regardless of its bonus. An incorporeal creature's 50% reduction in damage from corporeal sources does not apply to attacks made against it with ghost touch weapons."}},
   {"MindBladeWeaponEnchancementKeen",new[]{"Psychic Weapon - Keen","A mindblade can add the keen property to her psychic weapon, but this consumes 1 point of enhancement bonus granted to this weapon.\nThe keen property doubles the threat range of a weapon. This benefit doesn't stack with any other effects that expand the threat range of a weapon (such as the keen edge spell or the Improved Critical feat)."}},
   {"MindBladeWeaponEnchancementHoly",new[]{"Psychic Weapon - Holy","A mindblade can add the holy property to her psychic weapon, but this consumes 2 points of enhancement bonus granted to this weapon.\nA holy weapon is imbued with holy power. This power makes the weapon good-aligned and thus overcomes the corresponding damage reduction. It deals an extra 2d6 points of damage against all creatures of evil alignment."}},
   {"MindBladeWeaponEnchancementUnholy",new[]{"Psychic Weapon - Unholy","A mindblade can add the unholy property to her psychic weapon, but this consumes 2 points of enhancement bonus granted to this weapon.\nAn unholy weapon is imbued with unholy power. This power makes the weapon evil-aligned and thus overcomes the corresponding damage reduction. It deals an extra 2d6 points of damage against all creatures of good alignment."}},
   {"MindBladeWeaponEnchancementAxiomatic",new[]{"Psychic Weapon - Axiomatic","A mindblade can add the axiomatic property to her psychic weapon, but this consumes 2 points of enhancement bonus granted to this weapon.\nAn axiomatic weapon is infused with lawful power. It makes the weapon lawful-aligned and thus overcomes the corresponding damage reduction. It deals an extra 2d6 points of damage against chaotic creatures."}},
   {"MindBladeWeaponEnchancementAnarchic",new[]{"Psychic Weapon - Anarchic","A mindblade can add the anarchic property to her psychic weapon, but this consumes 2 points of enhancement bonus granted to this weapon.\nAn anarchic weapon is infused with the power of chaos. It makes the weapon chaotic-aligned and thus overcomes the corresponding damage reduction. It deals an extra 2d6 points of damage against all creatures of lawful alignment."}},
   {"MindBladeWeaponEnchancementBane",new[]{"Psychic Weapon - Bane","A mindblade can add the bane property to her psychic weapon(s), but she needs to pay 1 extra point from her psychic pool per manifested weapon (double weapons count as two weapons). These extra points are not recovered upon dismissing manifested weapons.\nA bane weapon excels against certain foes. Against a designated foe, the weapon's enhancement bonus is +2 better than its actual bonus. It also deals an extra 2d6 points of damage against such foes."}},
   {"AllowTwoPsychicWeaponsBuff",new[]{"Dual Weapons","At 7th level, a mindblade can maintain two psychic weapons at a time or a psychic double weapon, though each weapon (or each end of a double weapon) has an enhancement bonus 1 lower than normal. Starting at 12th level, each of the two psychic weapons (or each end of a double weapon) instead has an enhancement bonus 2 lower than normal. When using two-weapon fighting with two psychic weapons or a psychic double weapon, the mindblade can use her spell combat ability as though she had a hand free."}},
   {"ManifestWeaponDeactivateAbility",new[]{"Deactivate Manifested Weapon(s)","Dismiss manifested weapon(s) and recover spent psychic pool points."}},
   {"DualWeaponsFeature",new[]{"Dual Weapons","At 7th level, a mindblade can maintain two psychic weapons at a time or a psychic double weapon, though each weapon (or each end of a double weapon) has an enhancement bonus 1 lower than normal. Starting at 12th level, each of the two psychic weapons (or each end of a double weapon) instead has an enhancement bonus 2 lower than normal. When using two-weapon fighting with two psychic weapons or a psychic double weapon, the mindblade can use her spell combat ability as though she had a hand free."}},
   {"MindBladeRapidManifestFeature",new[]{"Rapid Manifest","At 8th level, a mindblade can manifest one psychic weapon as a swift action."}},
   {"MindBladeDualManifestFeature",new[]{"Dual Manifest","At 13th level, a mindblade can manifest two psychic weapons or one double weapon with a swift action. Also, when wielding a psychic weapon two-handed, she can use her spell combat ability as though she had a hand free."}},
   {"PsychicPoolFeature",new[]{"Psychic Pool","A mindblade gains a psychic pool, similar to a normal magus’s arcane pool. At 1st level, a mindblade can expend 1 point from her psychic pool as a standard action to manifest a light melee weapon of her choice, formed from psychic energy. By spending 2 points, the mindblade can manifest a one-handed melee weapon, and by spending 3 points, she can manifest a two-handed melee weapon (but not a double weapon). This psychic weapon can last indefinitely, but it vanishes if it leaves the mindblade’s hand. The mindblade can dismiss a held psychic weapon as a free action. When a psychic weapon vanishes, the mindblade regains the psychic energy used to create it. She can maintain only one weapon at a time.\nAt 1st level, a psychic weapon counts as a magic weapon of whatever type the mindblade selected, with a +1 enhancement bonus. At 3rd level and every 3 levels thereafter, the weapon’s enhancement bonus increases by 1, up to maximum of +5 at 12th level. Starting at 5th level, the mindblade can add any of the weapon special abilities listed in the arcane pool class feature in place of these bonuses. At 15th and 18th levels, the weapon gains an additional +1 enhancement bonus, which the mindblade can spend only on weapon special abilities."}},
  };
  internal static string Name(string key)=>Rows.TryGetValue(key,out var row)?row[0]:throw new InvalidOperationException("Original CotW name missing: "+key);
  internal static string Text(string key)=>Rows.TryGetValue(key,out var row)?row[1]:throw new InvalidOperationException("Original CotW description missing: "+key);
 }
}
